9	
10	#[cfg_attr(coverage_nightly, coverage(off))]
11	mod sol {
12	    use alloy_sol_macro::sol;
13	
14	    sol! {
15	        /// There's no code at `target` (it is not a contract).
16	        ///
17	        /// * `target` - Address of the target contract.
18	        #[derive(Debug)]
19	        #[allow(missing_docs)]
20	        error AddressEmptyCode(address target);
21	
22	        /// A call to an address target failed. The target may have reverted
23	        /// without a revert reason.
24	        #[derive(Debug)]
25	        #[allow(missing_docs)]
26	        error FailedCall();
27	
28	        /// A call to an address target failed. The target may have reverted
29	        /// with a reason.
30	        ///
31	        /// * `reason` - The revert reason that was returned by the call.
32	        #[derive(Debug)]
33	        #[allow(missing_docs)]
34	        error FailedCallWithReason(bytes reason);
35	    }
36	}
