38	/// An [`AddressUtils`] error.
39	#[derive(SolidityError, Debug)]
40	pub enum Error {
41	    /// There's no code at `target` (it is not a contract).
42	    EmptyCode(AddressEmptyCode),
43	    /// A call to an address target failed. The target may have reverted
44	    /// without a revert reason.
45	    FailedCall(FailedCall),
46	    /// A call to an address target failed. The target may have reverted
47	    /// with a reason.
48	    FailedCallWithReason(FailedCallWithReason)}
49	
50	impl MethodError for Error {
51	    fn encode(self) -> alloc::vec::Vec<u8> {
52	        self.into()
53	    }
54	}
55	
56	/// A collection of utilities for working with [`Address`].
57	pub struct AddressUtils;
58	
59	impl AddressUtils {
60	    /// Performs a delegate call to `target` with the given `data`.
61	    ///
62	    /// # Arguments
63	    ///
64	    /// * `context` - Mutable access to the contract's state.
65	    /// * `target` - The address of the target contract.
66	    /// * `data` - The data to pass to the target contract.
67	    ///
68	    /// # Errors
69	    ///
70	    /// * [`Error::FailedCall`] - If the call to the target contract fails
71	    ///   without a revert reason.
72	    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
73	    ///   fails with a revert reason or if the call fails for any other reason.
74	    /// * [`Error::EmptyCode`] - If the target contract has no code.
75	    pub(crate) fn has_code(context: &impl HostAccess<Host = VM>, account: Address) -> bool {
76	        context.vm().code_size(account) > 0
77	    }
78	
79	    pub fn function_delegate_call(
80	        context: &mut (impl TopLevelStorage + HostAccess<Host = VM>),
81	        target: Address,
82	        data: &[u8],
83	    ) -> Result<Vec<u8>, Error> {
84	        let call = Call::new_mutating(context);
85	        let result =
86	            unsafe { call::delegate_call(context.vm(), call, target, data) };
87	        Self::verify_call_result_from_target(context, target, result)
88	    }
89	
90	    // TODO: Support more result types out of the box (e.g. `U256`, `U160`,
91	    // `String`, etc.).
92	    /// Helper function to verify that a low level call to smart-contract was
93	    /// successful.
94	    ///
95	    /// Reverts if the target was not a contract or if the call fails for any
96	    /// other reason. Bubbles up the revert reason (falling back to
97	    /// [`Error::FailedCall`]) in case of an unsuccessful call.
98	    ///
99	    /// # Arguments
100	    ///
101	    /// * `target` - The address of the target contract.
102	    /// * `result` - The result of the call.
103	    ///
104	    /// # Errors
105	    ///
106	    /// * [`Error::EmptyCode`] - If the target contract has no code.
107	    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
108	    ///   fails with a revert reason or if the call fails for any other reason.
109	    /// * [`Error::FailedCall`] - If the call to the target contract fails
110	    ///   without a revert reason.
111	    pub fn verify_call_result_from_target<T: AsRef<[u8]>>(
112	        context: &impl HostAccess<Host = VM>,
113	        target: Address,
114	        result: Result<T, stylus_sdk::stylus_core::calls::errors::Error>,
115	    ) -> Result<T, Error> {
116	        match result {
117	            Ok(returndata) => {
118	                if returndata.as_ref().is_empty() && context.vm().code_size(target) == 0 {
119	                    return Err(AddressEmptyCode { target }.into());
120	                }
121	                Ok(returndata)
122	            }
123	            Err(e) => Err(Self::revert(e))}
124	    }
125	}
126	
127	impl AddressUtils {
128	    /// Reverts with `error` if revert reason exists. Otherwise reverts with
129	    /// [`Error::FailedCall`].
130	    ///
131	    /// This behavior is aligned with Solidity implementation of
132	    /// [Address.sol].
133	    ///
134	    /// [Address.sol]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/utils/Address.sol
135	    fn revert(error: stylus_sdk::stylus_core::calls::errors::Error) -> Error {
136	        match &error {
137	            stylus_sdk::stylus_core::calls::errors::Error::Revert(data) if data.is_empty() => {
138	                FailedCall {}.into()
139	            }
140	            _ => FailedCallWithReason { reason: error.encode().into() }.into()}
141	    }
142	}
