1	//! Helper for reading and writing primitive types to specific storage slots.
2	use alloy_primitives::U256;
3	use stylus_sdk::{host::VM, prelude::*};
4	
5	const SLOT_BYTE_SPACE: u8 = 32;
6	
7	/// Helper for reading and writing primitive types to specific storage slots.
8	///
9	/// Storage slots are often used to avoid storage conflict when dealing with
10	/// upgradeable contracts. This library helps with reading and writing to such
11	/// slots without the need for low-level operations.
12	///
13	/// The functions in this library return appropriate storage types that contain
14	/// a `value` member that can be used to read or write.
15	///
16	/// Example usage to set ERC-1967 implementation slot:
17	///
18	/// ```rust
19	/// extern crate alloc;
20	///
21	/// use alloc::{vec, vec::Vec};
22	/// use alloy_primitives::{b256, Address, B256};
23	/// use openzeppelin_stylus::utils::storage_slot::StorageSlot;
24	/// use stylus_sdk::{storage::StorageAddress, prelude::*};
25	///
26	/// const IMPLEMENTATION_SLOT: B256 = b256!("0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc");
27	///
28	/// #[storage]
29	/// #[entrypoint]
30	/// pub struct Erc1967;
31	///
32	/// #[public]
33	/// impl Erc1967 {
34	///     fn get_implementation(&self) -> Address {
35	///         return StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).get();
36	///     }
37	///
38	///     fn set_implementation(&mut self, new_implementation: Address) {
39	///         assert!(new_implementation.has_code());
40	///         StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).set(new_implementation);
41	///     }
42	/// }
43	/// ```
44	pub struct StorageSlot;
45	
46	impl StorageSlot {
47	    /// Returns a [`StorageType`] located at `slot`.
48	    ///
49	    /// # Arguments
50	    ///
51	    /// * `slot` - The slot to get the address from.
52	    #[must_use]
53	    pub fn get_slot<ST: StorageType>(
54	        context: &impl HostAccess<Host = VM>,
55	        slot: impl Into<U256>,
56	    ) -> ST {
57	        // SAFETY: Truncation is safe here because ST::SLOT_BYTES is never
58	        // larger than 32, so the subtraction cannot underflow and the
59	        // cast is always valid.
60	        #[allow(clippy::cast_possible_truncation)]
61	        unsafe {
62	            ST::new(
63	                slot.into(),
64	                SLOT_BYTE_SPACE - ST::SLOT_BYTES as u8,
65	                context.vm().clone(),
66	            )
67	        }
68	    }
69	}
70	
71	#[cfg(test)]
72	mod tests {
73	    #![allow(clippy::unused_self)]
74	
75	    use alloy_primitives::{uint, Address, U256};
76	    use motsu::prelude::*;
77	    use stylus_sdk::storage::StorageAddress;
78	
79	    use super::*;
80	
81	    const IMPLEMENTATION_SLOT: U256 = uint!(12345_U256);
82	
83	    #[storage]
84	    #[entrypoint]
85	    pub struct Erc1967 {
86	        address: StorageAddress}
87	
88	    #[public]
89	    impl Erc1967 {
90	        fn get_implementation(&self) -> Address {
91	            StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).get()
92	        }
93	
94	        fn set_implementation(&self, new_implementation: Address) {
95	            StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT)
96	                .set(new_implementation);
97	        }
98	
99	        fn get_address(&self) -> Address {
100	            self.address.get()
101	        }
102	
103	        fn set_address(&mut self, new_address: Address) {
104	            self.address.set(new_address);
105	        }
106	
107	        fn get_address_at_zero_slot(&self) -> Address {
108	            StorageSlot::get_slot::<StorageAddress>(U256::ZERO).get()
109	        }
110	
111	        fn set_address_at_zero_slot(&mut self, new_address: Address) {
112	            StorageSlot::get_slot::<StorageAddress>(U256::ZERO)
113	                .set(new_address);
114	        }
115	    }
116	
117	    #[motsu::test]
118	    fn test_storage_slot(
119	        contract: Contract<Erc1967>,
120	        alice: Address,
121	        impl_address: Address,
122	    ) {
123	        let implementation = contract.sender(alice).get_implementation();
124	        assert_eq!(implementation, Address::ZERO);
125	
126	        contract.sender(alice).set_implementation(impl_address);
127	
128	        let implementation = contract.sender(alice).get_implementation();
129	        assert_eq!(implementation, impl_address);
130	        let address = contract.sender(alice).get_address_at_zero_slot();
131	        assert_eq!(address, Address::ZERO);
132	        let address = contract.sender(alice).get_address();
133	        assert_eq!(address, Address::ZERO);
134	
135	        contract.sender(alice).set_address(impl_address);
136	
137	        let implementation = contract.sender(alice).get_implementation();
138	        assert_eq!(implementation, impl_address);
139	        let address = contract.sender(alice).get_address_at_zero_slot();
140	        assert_eq!(address, impl_address);
141	        let address = contract.sender(alice).get_address();
142	        assert_eq!(address, impl_address);
143	
144	        contract.sender(alice).set_address_at_zero_slot(alice);
145	
146	        let implementation = contract.sender(alice).get_implementation();
147	        assert_eq!(implementation, impl_address);
148	        let address = contract.sender(alice).get_address_at_zero_slot();
149	        assert_eq!(address, alice);
150	        let address = contract.sender(alice).get_address();
151	        assert_eq!(address, alice);
152	    }
153	}
