    /// # use stylus_test::TestVM;
    /// # use alloy_primitives::{Address, U256};
    /// let vm = TestVM::new();
    /// let addr = Address::from([1u8; 20]);
    /// vm.set_balance(addr, U256::from(1000));
    /// ```
    pub fn set_balance(&self, address: Address, balance: U256) {
