1	//! Elliptic Curve Digital Signature Algorithm (ECDSA) operations.
2	//!
3	//! These functions can be used to verify that a message was signed
4	//! by the holder of the private keys of a given address.
5	use alloc::vec::Vec;
6	use stylus_sdk::stylus_core::calls::errors::MethodError;
7	
8	use alloy_primitives::{address, uint, Address, B256, U256};
9	use alloy_sol_types::SolType;
10	use stylus_sdk::{call, prelude::*};
11	
12	/// Address of the `ecRecover` EVM precompile.
13	pub const ECRECOVER_ADDR: Address =
14	    address!("0000000000000000000000000000000000000001");
15	
16	/// Upper range for `s` value from the signature.
17	pub const SIGNATURE_S_UPPER_BOUND: U256 = uint!(
18	    0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0_U256
19	);
20	
21	pub use sol::*;
22	#[cfg_attr(coverage_nightly, coverage(off))]
23	mod sol {
24	    use alloy_sol_macro::sol;
25	
26	    sol! {
27	        /// The signature derives the [`Address::ZERO`].
28	        #[derive(Debug)]
29	        #[allow(missing_docs)]
30	        error ECDSAInvalidSignature();
31	
32	        /// The signature has an `S` value that is in the upper half order.
33	        ///
34	        /// * `s` - Invalid `S` value.
35	        #[derive(Debug)]
36	        #[allow(missing_docs)]
37	        error ECDSAInvalidSignatureS(bytes32 s);
38	    }
39	
40	    sol! {
41	        /// Struct with callable data to the `ecRecover` precompile.
42	        #[allow(missing_docs)]
43	        struct EcRecoverData {
44	            /// EIP-191 Hash of the message.
45	            bytes32 hash;
46	            /// `v` value from the signature.
47	            uint8 v;
48	            /// `r` value from the signature.
49	            bytes32 r;
50	            /// `s` value from the signature.
51	            bytes32 s;
52	        }
53	    }
54	}
