        let vm = TestVM::new();
        let data = vec![0xaa, 0xbb, 0xcc, 0xdd, 0xee];
        vm.write_result(&data);

        let result = vm.read_return_data(3, Some(10));
        assert_eq!(result, vec![0xdd, 0xee]);
    }

