275	/// Ed25519 signature representation.
276	///
277	/// Signature verification libraries are expected to reject invalid
278	/// field elements at the time a signature is verified.
279	#[derive(Copy, Clone, Eq, PartialEq)]
280	pub struct Signature {
281	    /// `R` is an `EdwardsPoint`, formed by using an hash function with
282	    /// `512-bits` output to produce the digest of:
283	    ///
284	    /// * the nonce half of the `ExpandedSecretKey`, and
285	    /// * the message to be signed.
286	    ///
287	    /// This digest is then interpreted as a `Scalar` and reduced into an
288	    /// element in ℤ/lℤ.  The scalar is then multiplied by the distinguished
289	    /// basepoint to produce `R`, and `EdwardsPoint`.
290	    pub R: ProjectivePoint,
291	
292	    /// `s` is a `Scalar`, formed by using a hash function with `512-bits`
293	    /// output to produce the digest of:
294	    ///
295	    /// * the `r` portion of this `Signature`,
296	    /// * the `PublicKey` which should be used to verify this `Signature`, and
297	    /// * the message to be signed.
298	    ///
299	    /// This digest is then interpreted as a `Scalar` and reduced into an
300	    /// element in ℤ/lℤ.
301	    pub s: Scalar,
302	}
303	
304	impl Signature {
305	    /// Converts the signature to a 64-byte array.
306	    ///
307	    /// The first 32 bytes contain the compressed encoding of the `R` value.
308	    /// The last 32 bytes contain the canonical encoding of the `s` scalar.
309	    #[must_use]
310	    pub fn to_bytes(&self) -> [u8; SIGNATURE_LENGTH] {
311	        let mut bytes = [0u8; 64];
312	
313	        // Get the compressed representation of R
314	        let r_compressed = CompressedPointY::from(self.R.into_affine());
315	        bytes[..32].copy_from_slice(r_compressed.as_ref());
316	
317	        // Get the little-endian byte representation of s
318	        let s_bytes = self.s.into_bigint().into_bytes_le();
319	        bytes[32..].copy_from_slice(&s_bytes[..32]);
320	
321	        bytes
322	    }
323	
324	    /// Construct a signature from affine point `R` and scalar `s`.
325	    #[must_use]
326	    pub fn from_affine_R_s(R: AffinePoint, s: Scalar) -> Self {
327	        Signature { R: R.into(), s }
328	    }
329	}
330	
331	/// Ed25519 key for signature verification (public key).
332	#[derive(Copy, Clone, Default, PartialEq)]
333	pub struct VerifyingKey {
334	    /// Edwards point used for curve arithmetic operations.
335	    pub point: ProjectivePoint,
336	}
337	
338	impl VerifyingKey {
339	    /// Construct verifying key from affine point.
340	    #[must_use]
341	    pub fn from_affine(point: AffinePoint) -> Self {
342	        VerifyingKey { point: point.into() }
343	    }
344	
345	    /// Verify a signature on a message with this keypair's public key.
346	    #[must_use]
347	    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
348	        let expected_r = self.compute_R(signature, message);
349	        expected_r == signature.R
350	    }
351	
352	    /// Helper for verification. Computes the expected `R` component of the
353	    /// signature. The caller compares this to the real `R` component.
354	    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
355	    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
356	    fn compute_R(
357	        &self,
358	        signature: &Signature,
359	        message: &[u8],
360	    ) -> ProjectivePoint {
361	        let R = signature.R;
362	        let A = self.point;
363	
364	        let mut h = Sha512::new();
365	        h.update(CompressedPointY::from(R.into_affine()));
366	        h.update(CompressedPointY::from(A.into_affine()));
367	        h.update(message);
368	
369	        let k = WideScalar::from_bigint(U512::from_bytes_le(
370	            h.finalize().as_slice(),
371	        ));
372	        let k = Scalar::from_fp(k);
373	
374	        // Compute R: `-[k]A + [s]B = R`.
375	        A * (-k) + ProjectivePoint::generator() * signature.s
376	    }
377	
378	    /// Convert the [`VerifyingKey`] to a compressed byte representation.
379	    #[inline]
380	    #[must_use]
381	    pub fn to_bytes(&self) -> PublicKey {
382	        CompressedPointY::from(self.point.into_affine()).into()
383	    }
384	}
385	
386	impl From<ProjectivePoint> for VerifyingKey {
387	    fn from(point: ProjectivePoint) -> Self {
388	        VerifyingKey { point }
389	    }
390	}
391	
392	impl From<ExpandedSecretKey> for VerifyingKey {
393	    fn from(value: ExpandedSecretKey) -> Self {
394	        let point = ProjectivePoint::generator() * value.scalar;
395	        point.into()
396	    }
397	}
