            &mut self,
            receiver: Address,
            size: usize,
        ) -> (Vec<U256>, Vec<U256>) {
            let token_ids = random_token_ids(size);
            let values = random_values(size);

            self._mint_batch(
                receiver,
                token_ids.clone(),
                values.clone(),
                &vec![0, 1, 2, 3].into(),
            )
            .expect("Mint failed");
            (token_ids, values)
        }
    }

    fn append(values: Vec<U256>, value: u64) -> Vec<U256> {
        values.into_iter().chain(std::iter::once(U256::from(value))).collect()
    }

