41	const fn widening_mul_wasm(a: Limb, b: Limb) -> WideLimb {
42	    let a_lo = a as u32 as Limb;
43	    let a_hi = a >> 32;
44	    let b_lo = b as u32 as Limb;
45	    let b_hi = b >> 32;
