25	        /// This event gets emitted when the metadata of a token is changed.
26	        ///
27	        /// The event comes from IERC4096.
28	        #[derive(Debug)]
29	        #[allow(missing_docs)]
30	        event MetadataUpdate(uint256 token_id);
31	
32	        /// This event gets emitted when the metadata of a range of tokens
33	        /// is changed.
34	        ///
35	        /// The event comes from IERC4096.
36	        #[derive(Debug)]
37	        #[allow(missing_docs)]
38	        event BatchMetadataUpdate(uint256 from_token_id, uint256 to_token_id);
39	    }
40	}
