42	/// State of an [`Erc721UriStorage`] contract.
43	#[storage]
44	pub struct Erc721UriStorage {
45	    /// Optional mapping for token URIs.
46	    pub token_uris: StorageMap<U256, StorageString>,
47	}
48	
49	/// Interface of an optional extension ERC-721 token providing storage based
50	/// token URI management.
51	pub trait IErc721UriStorage: IErc721Metadata {}
52	
53	impl Erc721UriStorage {
54	    /// Sets `token_uri` as the token URI of `token_id`.
55	    ///
56	    /// # Arguments
57	    ///
58	    /// * `&mut self` - Write access to the contract's state.
59	    /// * `token_id` - Id of a token.
60	    /// * `token_uri` - URI for the token.
61	    ///
62	    /// # Events
63	    ///
64	    /// * [`MetadataUpdate`].
65	    pub fn _set_token_uri(&mut self, token_id: U256, token_uri: String) {
66	        self.token_uris.setter(token_id).set_str(token_uri);
67	        evm::log(MetadataUpdate { token_id });
68	    }
69	
70	    /// Check [`IErc721Metadata::token_uri()`] for more details.
71	    #[allow(clippy::missing_errors_doc)]
72	    pub fn token_uri(
73	        &self,
74	        token_id: U256,
75	        erc721: &impl IErc721<Error = erc721::Error>,
76	        metadata: &Erc721Metadata,
77	    ) -> Result<String, erc721::Error> {
78	        erc721.owner_of(token_id)?;
79	
80	        let token_uri = self.token_uris.getter(token_id).get_string();
81	        let base = metadata.base_uri();
82	
83	        // If there is no base URI, return the token URI.
84	        if base.is_empty() {
85	            return Ok(token_uri);
86	        }
87	
88	        // If both are set, concatenate the `base_uri` and `token_uri`.
89	        let uri = if token_uri.is_empty() {
90	            metadata.token_uri(token_id, erc721)?
91	        } else {
92	            base + &token_uri
93	        };
94	
95	        Ok(uri)
96	    }
97	}
