18	/// State of an [`Erc721Metadata`] contract.
19	#[storage]
20	pub struct Erc721Metadata {
21	    /// [`Metadata`] contract.
22	    pub(crate) metadata: Metadata,
23	    // TODO: Remove this field once function overriding is possible. For now we
24	    // keep this field `pub`, since this is used to simulate overriding.
25	    /// Base URI for tokens.
26	    pub base_uri: StorageString,
27	}
28	
29	/// Interface for the optional metadata functions from the ERC-721 standard.
30	#[interface_id]
31	pub trait IErc721Metadata: IErc165 {
32	    /// The error type associated to this trait implementation.
33	    type Error: Into<alloc::vec::Vec<u8>>;
34	
35	    /// Returns the token collection name.
36	    ///
37	    /// # Arguments
38	    ///
39	    /// * `&self` - Read access to the contract's state.
40	    fn name(&self) -> String;
41	
42	    /// Returns token collection symbol.
43	    ///
44	    /// # Arguments
45	    ///
46	    /// * `&self` - Read access to the contract's state.
47	    fn symbol(&self) -> String;
48	
49	    /// Returns the Uniform Resource Identifier (URI) for `token_id` token.
50	    ///
51	    /// NOTE: The implementation should use `#[selector(name = "tokenURI")]` to
52	    /// match Solidity's camelCase naming convention.
53	    ///
54	    /// # Arguments
55	    ///
56	    /// * `&self` - Read access to the contract's state.
57	    /// * `token_id` - ID of a token.
58	    ///
59	    /// # Errors
60	    ///
61	    /// * [`erc721::Error::NonexistentToken`] - If the token does not exist.
62	    #[selector(name = "tokenURI")]
63	    fn token_uri(&self, token_id: U256) -> Result<String, Self::Error>;
64	}
65	
66	impl Erc721Metadata {
67	    /// Constructor.
68	    ///
69	    /// # Arguments
70	    ///
71	    /// * `&mut self` - Write access to the contract's state.
72	    /// * `name` - Token name.
73	    /// * `symbol` - Token symbol.
74	    pub fn constructor(&mut self, name: String, symbol: String) {
75	        self.metadata.constructor(name, symbol);
76	    }
77	
78	    /// Check [`IErc721Metadata::name()`] for more details.
79	    pub fn name(&self) -> String {
80	        self.metadata.name()
81	    }
82	
83	    /// Check [`IErc721Metadata::symbol()`] for more details.
84	    pub fn symbol(&self) -> String {
85	        self.metadata.symbol()
86	    }
87	
88	    /// Returns the base of Uniform Resource Identifier (URI) for tokens'
89	    /// collection.
90	    ///
91	    /// # Arguments
92	    ///
93	    /// * `&self` - Read access to the contract's state.
94	    pub fn base_uri(&self) -> String {
95	        self.base_uri.get_string()
96	    }
97	
98	    /// Check [`IErc721Metadata::token_uri()`] for more details.
99	    #[allow(clippy::missing_errors_doc)]
100	    pub fn token_uri(
101	        &self,
102	        token_id: U256,
103	        erc721: &impl IErc721<Error = erc721::Error>,
104	    ) -> Result<String, erc721::Error> {
105	        erc721.owner_of(token_id)?;
106	
107	        let base_uri = self.base_uri();
108	
109	        let token_uri = if base_uri.is_empty() {
110	            String::new()
111	        } else {
112	            base_uri + &token_id.to_string()
113	        };
114	
115	        Ok(token_uri)
116	    }
117	}
