1	//! Pausable Contract.
2	//!
3	//! Contract module which allows implementing an emergency stop mechanism
4	//! that can be triggered by an authorized account.
5	//!
6	//! It provides functions [`Pausable::when_not_paused`]
7	//! and [`Pausable::when_paused`],
8	//! which can be added to the functions of your contract.
9	//!
10	//! Note that your contract will not be pausable by simply including this
11	//! module, only once and where you use [`Pausable::when_not_paused`].
12	//!
13	//! Note that [`Pausable::pause`] and [`Pausable::unpause`] methods are not
14	//! exposed by default.
15	//! You should expose them manually in your contract's abi.
16	
17	use alloc::{vec, vec::Vec};
18	
19	pub use sol::*;
20	use stylus_sdk::{
21	    call::MethodError, evm, msg, prelude::*, storage::StorageBool,
22	};
23	
24	#[cfg_attr(coverage_nightly, coverage(off))]
25	mod sol {
26	    use alloy_sol_macro::sol;
27	
28	    sol! {
29	        /// Emitted when pause is triggered by `account`.
30	        #[derive(Debug)]
31	        #[allow(missing_docs)]
32	        event Paused(address account);
33	
34	        /// Emitted when the pause is lifted by `account`.
35	        #[derive(Debug)]
36	        #[allow(missing_docs)]
37	        event Unpaused(address account);
38	    }
39	
40	    sol! {
41	        /// Indicates an error related to the operation that failed
42	        /// because the contract is paused.
43	        #[derive(Debug)]
44	        #[allow(missing_docs)]
45	        error EnforcedPause();
46	
47	        /// Indicates an error related to the operation that failed
48	        /// because the contract is not paused.
49	        #[derive(Debug)]
50	        #[allow(missing_docs)]
51	        error ExpectedPause();
52	    }
53	}
54	
55	/// A Pausable error.
56	#[derive(SolidityError, Debug)]
57	pub enum Error {
58	    /// Indicates an error related to the operation that failed
59	    /// because the contract had been in `Paused` state.
60	    EnforcedPause(EnforcedPause),
61	    /// Indicates an error related to the operation that failed
62	    /// because the contract had been in `Unpaused` state.
63	    ExpectedPause(ExpectedPause),
64	}
65	
66	impl MethodError for Error {
67	    fn encode(self) -> alloc::vec::Vec<u8> {
68	        self.into()
69	    }
70	}
71	
72	/// State of a [`Pausable`] Contract.
73	#[storage]
74	pub struct Pausable {
75	    /// Indicates whether the contract is `Paused`.
76	    pub(crate) paused: StorageBool,
77	}
78	
79	/// Pausable interface.
80	pub trait IPausable {
81	    /// Returns true if the contract is paused, and false otherwise.
82	    ///
83	    /// # Arguments
84	    ///
85	    /// * `&self` - Read access to the contract's state.
86	    fn paused(&self) -> bool;
87	}
88	
89	#[public]
90	#[implements(IPausable)]
91	impl Pausable {}
92	
93	#[public]
94	impl IPausable for Pausable {
95	    fn paused(&self) -> bool {
96	        self.paused.get()
97	    }
98	}
99	
100	impl Pausable {
101	    /// Triggers `Paused` state.
102	    ///
103	    /// # Arguments
104	    ///
105	    /// * `&mut self` - Write access to the contract's state.
106	    ///
107	    /// # Errors
108	    ///
109	    /// * [`Error::EnforcedPause`] - If the contract is in `Paused` state.
110	    pub fn pause(&mut self) -> Result<(), Error> {
111	        self.when_not_paused()?;
112	        self.paused.set(true);
113	        evm::log(Paused { account: msg::sender() });
114	        Ok(())
115	    }
116	
117	    /// Triggers `Unpaused` state.
118	    ///
119	    /// # Arguments
120	    ///
121	    /// * `&mut self` - Write access to the contract's state.
122	    ///
123	    /// # Errors
124	    ///
125	    /// * [`Error::ExpectedPause`] - If the contract is in `Unpaused` state.
126	    pub fn unpause(&mut self) -> Result<(), Error> {
127	        self.when_paused()?;
128	        self.paused.set(false);
129	        evm::log(Unpaused { account: msg::sender() });
130	        Ok(())
131	    }
132	
133	    /// Helper to make a function callable only when the contract is NOT
134	    /// paused.
135	    ///
136	    /// # Arguments
137	    ///
138	    /// * `&self` - Read access to the contract's state.
139	    ///
140	    /// # Errors
141	    ///
142	    /// * [`Error::EnforcedPause`] - If the contract is in the `Paused` state.
143	    pub fn when_not_paused(&self) -> Result<(), Error> {
144	        if self.paused.get() {
145	            return Err(Error::EnforcedPause(EnforcedPause {}));
146	        }
147	        Ok(())
148	    }
149	
150	    /// Helper to make a function callable
151	    /// only when the contract is paused.
152	    ///
153	    /// # Arguments
154	    ///
155	    /// * `&self` - Read access to the contract's state.
156	    ///
157	    /// # Errors
158	    ///
159	    /// * [`Error::ExpectedPause`] - If the contract is in `Unpaused` state.
160	    pub fn when_paused(&self) -> Result<(), Error> {
161	        if !self.paused.get() {
162	            return Err(Error::ExpectedPause(ExpectedPause {}));
163	        }
164	        Ok(())
165	    }
166	}
167	
168	#[cfg(test)]
169	mod tests {
170	    use alloy_primitives::Address;
171	    use motsu::prelude::Contract;
172	    use stylus_sdk::prelude::*;
173	
174	    use crate::utils::pausable::{Error, IPausable, Pausable};
175	
176	    unsafe impl TopLevelStorage for Pausable {}
177	
178	    #[motsu::test]
179	    fn paused_works(contract: Contract<Pausable>, alice: Address) {
180	        contract.sender(alice).paused.set(true);
181	        assert!(contract.sender(alice).paused());
182	
183	        contract.sender(alice).paused.set(false);
184	        assert!(!contract.sender(alice).paused());
185	    }

