    #[inline]
    fn abi_encode_returns(ret: &Self::Return) -> Vec<u8> {
        crate::abi::encode_sequence(&Self::tokenize_returns(ret))
    }

    /// ABI encode the call's return values.
    #[inline]
    fn abi_encode_returns_tuple<'a, E>(e: &'a E) -> Vec<u8>
