//! Experiments with TestVM semantics.
use alloy_primitives::{address, Address, U256};
use alloy_sol_types::SolValue;
use stylus_sdk::{prelude::*, testing::*};

#[test]
fn mock_return_data_is_last_registered() {
    let vm = TestVM::default();
    let target = address!("0x00000000000000000000000000000000000000aa");
    let other = address!("0x00000000000000000000000000000000000000bb");
    let a = vec![1u8, 2, 3];
    let b = vec![4u8, 5, 6, 7];
    vm.mock_static_call(target, vec![1], Ok(a.clone()));
    vm.mock_delegate_call(other, vec![2], Ok(b.clone()));

    // static call matched mock `a`, but returns `b`.
    let r = stylus_sdk::call::static_call(&vm, Call::new(), target, &[1]);
    println!("static matched: {:?}", r);
    let r = stylus_sdk::call::static_call(&vm, Call::new(), target, &[9]);
    println!("static unmatched: {:?}", r);

    vm.mock_delegate_call(other, vec![3], Err(vec![9, 9]));
    let r = unsafe { stylus_sdk::call::delegate_call(&vm, Call::new_mutating_for_test(), other, &[3]) };
    println!("delegate matched err: {:?}", r);
}

struct Dummy;
unsafe impl TopLevelStorage for Dummy {}
trait NewMutatingForTest { fn new_mutating_for_test() -> Call<true, false>; }
impl NewMutatingForTest for Call<true, false> {
    fn new_mutating_for_test() -> Call<true, false> {
        let mut d = Dummy;
        Call::new_mutating(&mut d)
    }
}
