// ---- flash mint success path
#[storage]
struct FlashExample {
    flash: Erc20FlashMint,
    erc20: Erc20,
}

#[test]
fn flash_loan_success_path() {
    let vm = TestVM::default();
    let mut c = FlashExample::from(&vm);
    let contract = vm.contract_address();
    vm.set_code(RECEIVER, vec![1]);

    let value = uint!(1000_U256);
    let fee = uint!(10_U256);
    c.flash.flash_fee_value.set(fee);
    c.flash.flash_fee_receiver_address.set(BOB);

    // The receiver approves the lender to burn value + fee, and holds the fee.
    c.erc20._mint(RECEIVER, fee).unwrap();
    c.erc20._approve(RECEIVER, contract, value + fee, false).unwrap();

    // Receiver callback returns the expected hash.
    vm.mock_call(
        RECEIVER,
        Calls::onFlashLoanCall {
            initiator: ALICE,
            token: contract,
            amount: value,
            fee,
            data: vec![1, 2].into(),
        }
        .abi_encode(),
        U256::ZERO,
        Ok(B256::from(BORROWER_CALLBACK_VALUE).abi_encode()),
    );

    vm.set_sender(ALICE);
    let ok = c
        .flash
        .flash_loan(RECEIVER, contract, value, &Bytes::from(vec![1, 2]), &mut c.erc20)
        .expect("flash loan should work");
    assert!(ok);
    // value minted to the receiver and burned back, fee moved to fee receiver.
    assert_eq!(c.erc20.balance_of(RECEIVER), U256::ZERO);
    assert_eq!(c.erc20.balance_of(BOB), fee);
    assert_eq!(c.erc20.total_supply(), fee);
}

#[test]
fn flash_loan_invalid_return_value() {
