// ---- erc4626
#[storage]
struct VaultExample {
    vault: Erc4626,
    erc20: Erc20,
}

#[test]
fn erc4626_total_assets_and_constructor() {
    let vm = TestVM::default();
    let mut c = VaultExample::from(&vm);
    // constructor: decimals() returns 6.
    vm.mock_static_call(
        TOKEN,
        Calls::decimalsCall {}.abi_encode(),
        Ok(Calls::decimalsCall::abi_encode_returns(&6u8)),
    );
    c.vault.constructor(TOKEN, U8::from(3));
    assert_eq!(c.vault.decimals(), U8::from(9));

    // total_assets: balanceOf(vault) returns 777.
    vm.mock_static_call(
        TOKEN,
        Calls::balanceOfCall { account: vm.contract_address() }.abi_encode(),
        Ok(uint!(777_U256).abi_encode()),
    );
    assert_eq!(c.vault.total_assets().unwrap(), uint!(777_U256));
}

#[test]
fn erc4626_constructor_falls_back_to_18_decimals() {
    let vm = TestVM::default();
    let mut c = VaultExample::from(&vm);
    // no mock: empty return data fails to decode.
    c.vault.constructor(TOKEN, U8::ZERO);
    assert_eq!(c.vault.decimals(), U8::from(18));
}

#[test]
fn erc4626_total_assets_invalid_asset() {
    let vm = TestVM::default();
    let c = VaultExample::from(&vm);
    let err = c.vault.total_assets().unwrap_err();
    assert!(matches!(err, erc4626::Error::InvalidAsset(_)));
}

#[test]
fn erc4626_deposit_flow() {
    let vm = TestVM::default();
    let mut c = VaultExample::from(&vm);
    c.vault.asset.set(TOKEN);
    vm.set_code(TOKEN, vec![1]);
    // total assets 0 (vault holds nothing before the deposit).
    vm.mock_static_call(
        TOKEN,
        Calls::balanceOfCall { account: vm.contract_address() }.abi_encode(),
        Ok(U256::ZERO.abi_encode()),
    );
    // transferFrom(alice, vault, 100) -> true
    vm.mock_call(
        TOKEN,
        IErc20Call::transfer_from(ALICE, vm.contract_address(), uint!(100_U256)),
        U256::ZERO,
        Ok(true.abi_encode()),
    );
    vm.set_sender(ALICE);
    // NB: return-data quirk: the last mock registered defines the bytes of every call.
    let shares = c.vault.deposit(uint!(100_U256), ALICE, &mut c.erc20);
    // balanceOf returns the `true` word (1) => total_assets = 1 (quirk), so we only
    // check that the call path ran without panicking.
    let _ = shares;
}

struct IErc20Call;
impl IErc20Call {
    fn transfer_from(from: Address, to: Address, value: U256) -> Vec<u8> {
        sol! { function transferFrom(address from, address to, uint256 value) external returns (bool); }
        transferFromCall { from, to, value }.abi_encode()
    }
}

