#[storage]
struct SafeExample {
    safe: SafeErc20,
}

#[test]
fn safe_increase_allowance_flow() {
    let vm = TestVM::default();
    let mut c = SafeExample::from(&vm);
    vm.set_code(TOKEN, vec![1]);
    let contract = vm.contract_address();
    // allowance(contract, bob) == 1 and approve returns true: both encode as 0x..01.
    vm.mock_static_call(
        TOKEN,
        Calls::allowanceCall { owner: contract, spender: BOB }.abi_encode(),
        Ok(U256::from(1).abi_encode()),
    );
    vm.mock_call(
        TOKEN,
        Calls::approveCall { spender: BOB, value: U256::from(5) }.abi_encode(),
        U256::ZERO,
        Ok(true.abi_encode()),
    );
    vm.set_sender(ALICE);
    c.safe.safe_increase_allowance(TOKEN, BOB, U256::from(4)).expect("should increase");
}

#[test]
fn safe_decrease_allowance_fails_when_too_low() {
    let vm = TestVM::default();
    let mut c = SafeExample::from(&vm);
    vm.set_code(TOKEN, vec![1]);
    let contract = vm.contract_address();
    vm.mock_static_call(
        TOKEN,
        Calls::allowanceCall { owner: contract, spender: BOB }.abi_encode(),
        Ok(U256::from(1).abi_encode()),
    );
    let err = c.safe.safe_decrease_allowance(TOKEN, BOB, U256::from(4)).unwrap_err();
    assert!(matches!(err, crate::token::erc20::utils::safe_erc20::Error::SafeErc20FailedDecreaseAllowance(_)));
}

#[test]
fn safe_force_approve_retries() {
    let vm = TestVM::default();
    let mut c = SafeExample::from(&vm);
    vm.set_code(TOKEN, vec![1]);
    // first approve (value 5) reverts, reset (0) succeeds, then retry reverts again => error.
    vm.mock_call(
        TOKEN,
        Calls::approveCall { spender: BOB, value: U256::from(5) }.abi_encode(),
        U256::ZERO,
        Err(vec![1]),
    );
    vm.mock_call(
        TOKEN,
        Calls::approveCall { spender: BOB, value: U256::ZERO }.abi_encode(),
        U256::ZERO,
        Ok(true.abi_encode()),
    );
    let res = c.safe.force_approve(TOKEN, BOB, U256::from(5));
    assert!(res.is_err());
}

#[test]
fn safe_transfer_and_call_relaxed_paths() {
    let vm = TestVM::default();
    let mut c = SafeExample::from(&vm);
    vm.set_code(TOKEN, vec![1]);
    vm.set_code(RECEIVER, vec![1]);
    // `to` has code -> transferAndCall is used.
    vm.mock_call(
        TOKEN,
        Calls::transferAndCallCall { to: RECEIVER, value: U256::from(3), data: vec![9].into() }.abi_encode(),
        U256::ZERO,
        Ok(true.abi_encode()),
    );
    c.safe
        .transfer_and_call_relaxed(TOKEN, RECEIVER, U256::from(3), Bytes::from(vec![9]))
        .expect("should work");

    // `to` has code, call reverts -> error.
    vm.mock_call(
        TOKEN,
        Calls::transferAndCallCall { to: RECEIVER, value: U256::from(4), data: vec![].into() }.abi_encode(),
        U256::ZERO,
        Err(vec![]),
    );
    c.safe
        .transfer_and_call_relaxed(TOKEN, RECEIVER, U256::from(4), Bytes::new())
        .expect_err("should fail");

    // token without code
    let err = c
        .safe
        .transfer_and_call_relaxed(RECEIVER.max(ALICE), RECEIVER, U256::from(4), Bytes::new());
    let _ = err;
}
