6	
7	/// Possible panic codes for a revert.
8	///
9	/// Taken from <https://github.com/NomicFoundation/hardhat/blob/main/packages/hardhat-chai-matchers/src/internal/reverted/panic.ts>
10	#[derive(Debug)]
11	#[allow(missing_docs)] // Pretty straightforward variant names.
12	pub enum PanicCode {
13	    AssertionError = 0x1,
14	    ArithmeticOverflow = 0x11,
15	    DivisionByZero = 0x12,
16	    EnumConversionOutOfBounds = 0x21,
17	    IncorrectlyEncodedStorageByteArray = 0x22,
18	    PopOnEmptyArray = 0x31,
19	    ArrayAccessOutOfBounds = 0x32,
20	    TooMuchMemoryAllocated = 0x41,
21	    ZeroInitializedVariable = 0x51,
22	}
23	
24	impl core::fmt::Display for PanicCode {
25	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
26	        let msg = match self {
27	            PanicCode::AssertionError =>
28	                "Assertion error",
29	            PanicCode::ArithmeticOverflow =>
30	                "Arithmetic operation overflowed outside of an unchecked block",
31	            PanicCode::DivisionByZero =>
32	                "Division or modulo division by zero",
33	            PanicCode::EnumConversionOutOfBounds =>
34	                "Tried to convert a value into an enum, but the value was too big or negative",
35	            PanicCode::IncorrectlyEncodedStorageByteArray =>
36	                "Incorrectly encoded storage byte array",
37	            PanicCode::PopOnEmptyArray =>
38	                ".pop() was called on an empty array",
39	            PanicCode::ArrayAccessOutOfBounds =>
40	                "Array accessed at an out-of-bounds or negative index",
41	            PanicCode::TooMuchMemoryAllocated =>
42	                "Too much memory was allocated, or an array was created that is too large",
43	            PanicCode::ZeroInitializedVariable =>
44	                "Called a zero-initialized variable of internal function type"
45	        };
46	
47	        write!(f, "{msg}")
48	    }
49	}
50	
51	/// An error representing a panic.
52	pub trait Panic {
53	    /// Checks that `Self` corresponds to a panic with code `code`.
54	    fn panicked_with(&self, code: PanicCode) -> bool;
55	}
56	
57	/// An error representing a revert with some data.
58	pub trait Revert<E> {
59	    /// Checks that `Self` corresponds to the typed abi-encoded error
60	    /// `expected`.
61	    fn reverted_with(&self, expected: E) -> bool;
62	}
63	
64	impl Panic for alloy::contract::Error {
65	    fn panicked_with(&self, _code: PanicCode) -> bool {
66	        let Self::TransportError(e) = self else {
67	            return false;
68	        };
69	
70	        // FIXME: right now we cannot have any better error code for Panics
71	        // check `e`:
72	        //  ErrorResp(
73	        //      ErrorPayload {
74	        //          code: -32000,
75	        //          message: "execution reverted",
76	        //          data: None,
77	        //      },
78	        //  )
79	        let payload = e.as_error_resp().expect("should contain payload");
80	        payload.code == -32000 && payload.message == "execution reverted"
81	    }
82	}
83	
84	impl<E: MethodError> Revert<E> for alloy::contract::Error {
85	    fn reverted_with(&self, expected: E) -> bool {
86	        let Self::TransportError(e) = self else {
87	            return false;
88	        };
89	
90	        let raw_value = e
91	            .as_error_resp()
92	            .and_then(|payload| payload.data.clone())
93	            .expect("should extract the error");
94	
95	        let actual = &raw_value.get().trim_matches('"')[2..];
96	        let expected = alloy::hex::encode(expected.encode());
97	        expected == actual
98	    }
99	}
100	
101	impl<E: SolError> Revert<E> for eyre::Report {
102	    fn reverted_with(&self, expected: E) -> bool {
103	        // Generic revert error
104	        let Some(received) = self
105	            .chain()
106	            .find_map(|err| err.downcast_ref::<RpcError<TransportErrorKind>>())
107	        else {
108	            return false;
109	        };
110	        let RpcError::ErrorResp(received) = received else {
111	            return false;
112	        };
113	        let Some(received) = &received.data else {
114	            return false;
115	        };
116	        let expected = alloy::hex::encode(expected.abi_encode());
117	        received.to_string().contains(&expected)
118	    }
119	}
