359	        let name = node.sig.ident.clone();
360	        let (sol_name, name_err) = verify_sol_name(&kind, name.to_string(), selector_override);
361	        if let Some(err) = name_err {
362	            emit_error!(node.span(), err);
363	        }
364	        let sol_name = syn_solidity::SolIdent::new(&sol_name);
365	
366	        // determine state mutability
367	        let (inferred_purity, has_self) = Purity::infer(&node.sig);
368	        let purity = if payable || matches!(kind, FnKind::Receive) {
369	            Purity::Payable
370	        } else {
371	            inferred_purity
372	        };
373	
374	        let mut args = node.sig.inputs.iter();
375	        if inferred_purity > Purity::Pure {
376	            // skip self or storage argument
377	            args.next();
378	        }
379	        let inputs = match kind {
380	            FnKind::Function | FnKind::Constructor => args.map(PublicFnArg::from).collect(),
381	            _ => Vec::new(),
382	        };
383	        let input_span = node.sig.inputs.span();
384	
385	        let output = match &node.sig.output {
386	            syn::ReturnType::Default => None,
387	            syn::ReturnType::Type(_, ty) => Some(*ty.clone()),
388	        };
389	        let output_span = output
390	            .as_ref()
391	            .map(Spanned::span)
392	            .unwrap_or(node.sig.output.span());
393	
394	        let extension = E::build(node);
395	        Self {
396	            name,
397	            sol_name,
398	            purity,
399	            inferred_purity,
400	            kind,
401	
402	            has_self,
403	            inputs,
404	            input_span,
405	            output: node.sig.output.clone(),
406	            output_span,
407	
408	            extension,
409	        }
410	    }
411	}
