419	                    use alloc::vec;
420	
421	                    #(#selector_consts)*
422	                    match selector {
423	                        #(#selector_arms)*
424	                        _ => {
425	                            #(#implements_routes)*
426	                            None
427	                        }
428	                    }
429	                }
430	
431	                #[inline(always)]
432	                fn fallback(storage: &mut S, input: &[u8]) -> Option<stylus_sdk::ArbResult> {
433	                    #fallback
434	                }
435	
436	                #[inline(always)]
437	                fn receive(storage: &mut S) -> Option<Result<(), Vec<u8>>> {
438	                    #receive
439	                }
440	
441	                #[inline(always)]
442	                fn constructor(storage: &mut S, input: &[u8]) -> Option<stylus_sdk::ArbResult> {
443	                    #constructor
444	                }
445	            }
446	        }
447	    }
