42	/// An [`AddressUtils`] error.
43	#[derive(SolidityError, Debug)]
44	pub enum Error {
45	    /// There's no code at `target` (it is not a contract).
46	    EmptyCode(AddressEmptyCode),
47	    /// A call to an address target failed. The target may have reverted
48	    /// without a revert reason.
49	    FailedCall(FailedCall),
50	    /// A call to an address target failed. The target may have reverted
51	    /// with a reason.
52	    FailedCallWithReason(FailedCallWithReason),
53	}
