    76	        &mut self,
    77	        to: Address,
    78	        token_id: U256,
    79	        amount: U256,
    80	        data: Bytes,
    81	    ) -> Result<(), Error> {
    82	        // ...
    83	        self.pausable.when_not_paused()?;
    84	        // ...
    85	        self.erc1155._mint(to, token_id, amount, &data)?;
    86	        Ok(())
    87	    }
