    21	macro_rules! const_for {
    22	    (($i:ident in $start:tt.. $end:tt) $code:expr) => {{
    23	        let mut $i = $start;
    24	        loop {
    25	            $crate::cycle!($i, $end, $code);
    26	        }
    27	    }};
