    18	        impl BitIteratorBE for $int {
    19	            fn bit_be_iter(self) -> impl Iterator<Item = bool> {
    20	                (0..<$int>::BITS).rev().map(move |i| self & (1 << i) != 0)
    21	            }
    22	        }
    23	    };
    24	}
